    }
    if (targetFraction != null) commit(targetFraction);
  }

  void _cancelGesture(int pointer) {
    if (_activePointer != pointer) return;
    _activePointer = null;
    _pointerDownFraction = null;
    _dragMoved = false;
    if (_dragFraction != null && mounted) {
      setState(() {
        _dragFraction = null;
      });
    }
  }

