        Paint()
          ..color = fillColor
          ..strokeWidth = 1.5
          ..strokeCap = StrokeCap.square
          ..style = PaintingStyle.stroke,
      );
    }
  }

  @override
  bool shouldRepaint(covariant _SeekPainter old) =>
      old.fraction != fraction ||
      old.trackColor != trackColor ||
      old.fillColor != fillColor;
}

